// Запрос в API Канала: { url, token_env, body }, для SMS — { url, token_env, form }. Токен узел отправки
// берёт из $env[token_env], в данные выполнения он не попадает. Новый Канал = новая функция в CHANNELS.
const GRAPH = $env.META_GRAPH_BASE_URL;
// Вне окна 24 часов WhatsApp принимает только шаблон «есть новости»: одобрен у Meta на pl и en
// (docs/whatsapp-setup.md). Клиент отвечает на него — окно открывается снова.
const WHATSAPP_NEWS_TEMPLATE = 'news_update';

// Messenger и Instagram Direct — один Send API Messenger Platform, токен страницы: Instagram —
// страницы, связанной с аккаунтом Instagram. Вне окна 24 часов оба пускают только ответ человека
// с меткой HUMAN_AGENT (до 7 дней). Ответ Ассистента всегда в окне: он идёт сразу за сообщением Клиента.
function sendApi(token_env) {
  return (m) => ({
    url: `${GRAPH}/me/messages`,
    token_env,
    body: {
      recipient: { id: m.sender_id },
      ...(m.in_window ? { messaging_type: 'RESPONSE' } : { messaging_type: 'MESSAGE_TAG', tag: 'HUMAN_AGENT' }),
      message: { text: m.text },
    },
  });
}

function whatsappTemplate(name, language, parameters = []) {
  const body = parameters.length
    ? { components: [{ type: 'body', parameters: parameters.map((text) => ({ type: 'text', text })) }] }
    : {};
  return { type: 'template', template: { name, language: { code: language === 'pl' ? 'pl' : 'en' }, ...body } };
}

// Автоматизация (на входе template) идёт своим одобренным шаблоном в любое время, а не текстом.
function whatsappMessage(m) {
  if (m.template) return whatsappTemplate(m.template.name, m.language, m.template.parameters);
  if (m.in_window) return { type: 'text', text: { body: m.text } };
  return whatsappTemplate(WHATSAPP_NEWS_TEMPLATE, m.language);
}

function whatsapp(m) {
  return {
    url: `${GRAPH}/${m.account_id}/messages`,
    token_env: 'WHATSAPP_ACCESS_TOKEN',
    body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: m.sender_id, ...whatsappMessage(m) },
  };
}

// Messenger и Instagram Автоматизации не пускают (после 24 часов — только человек): Клиенту оттуда
// Автоматизация уходит SMS через SMSAPI на телефон Заявки. Поле отправителя — зарегистрированное
// в SMSAPI; пусто — поле по умолчанию аккаунта.
function sms(m) {
  if (!m.phone) throw new Error('Нет телефона Клиента: SMS Автоматизации не отправить');
  const form = { to: m.phone.replace(/^\+/, ''), message: m.text, encoding: 'utf-8', format: 'json' };
  if ($env.SMSAPI_SENDER) form.from = $env.SMSAPI_SENDER;
  // URLSearchParams в песочнице Code-узла нет.
  const encoded = Object.entries(form).map(([key, value]) => `${key}=${encodeURIComponent(value)}`).join('&');
  return { url: `${$env.SMSAPI_BASE_URL}/sms.do`, token_env: 'SMSAPI_TOKEN', form: encoded };
}

const CHANNELS = {
  messenger: sendApi('META_PAGE_ACCESS_TOKEN'),
  instagram: sendApi('INSTAGRAM_ACCESS_TOKEN'),
  whatsapp,
};
const template = $('Queue message').item.json.template;
const build = template && $json.channel !== 'whatsapp' ? sms : CHANNELS[$json.channel];
if (!build) throw new Error(`Канал ${$json.channel}: отправка не поддерживается`);
return { json: build({ ...$json, template }) };

// SMSAPI сообщает об ошибке в теле ответа (error, message), не только кодом HTTP.
if ($json.error) throw new Error(`SMSAPI ${$json.error}: ${$json.message}`);
return { json: $json };
